import{z as n,x as o,o as l,c as m,q as r,j as t,D as B,d as e,s,S as i,b as a}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"RM 上线前的验收清单","description":"","frontmatter":{"title":"RM 上线前的验收清单","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/rm-acceptance-checklist.md","filePath":"llm/rm-acceptance-checklist.md","lastUpdated":1791413859000}'),C={name:"llm/rm-acceptance-checklist.md"};function d(p,E,D,c,h,F){const A=o("Mermaid");return l(),m("div",null,[E[2]||(E[2]=r('<h1 id="rm-上线前的验收清单" tabindex="-1">RM 上线前的验收清单 <a class="header-anchor" href="#rm-上线前的验收清单" aria-label="Permalink to &quot;RM 上线前的验收清单&quot;">​</a></h1><div class="epigraph"><p>验收清单是把前面十四课的失效模式翻译成数字门：报告说明你想了什么，门说明你必须做到什么。</p><footer>—— 验收框架据 Llama 2 的消融与安全流程、InstructGPT 的迭代采集协议整理</footer></div><p><a href="/llm/rm-benchmarks">上一课</a>排好评测的三层漏斗；本课把漏斗变成门：一份新版 RM 从训练完成到接入 RL 之间必须通过的清单。工程上 RM 的失效极少是「全面变差」，几乎总是单点塌陷——某安全子域掉回随机、长度系数悄悄回正、重训后分数尺度漂了一倍。清单的价值在把「没人想到要看」变成「门不过就别上线」，把每一课的病对应成一个可执行的检查项。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>没有门的组织靠评审会放行：报告里放全局准确率与一张雷达图，评审依赖发言人的口径。三种典型事故都从这里过：其一，分域塌陷被均值吃掉——安全子域 0.55 藏在全局 0.74 里；其二，版本间不可比——重训后分数整体平移，与旧版数据混训的下游全部静默失配（<a href="/llm/rm-variance-policy">方差课</a>的归一化把漂移藏得更深）；其三，蒸馏版在冷门域崩——主流域正常，长尾域上学生没学到教师的判断（<a href="/llm/rm-distill-cascade">级联课</a>的已知边界）。清单因此不是流程装饰，是把已知失效模式各设一道数字门的工程纪律。</p><p><span class="marginnote">「验收门」翻译成大白话：自动化的放行考试——指标低于线就直接拦下，不靠开会拍板。它与「评审报告」的区别在方向：报告说明「我们想了什么」，门规定「必须做到什么才能过」，后者没法靠口才绕过。</span></p><h3 id="清单的五层" tabindex="-1">清单的五层 <a class="header-anchor" href="#清单的五层" aria-label="Permalink to &quot;清单的五层&quot;">​</a></h3><p>数据卡层：来源四类、配比矩阵、分域一致率 \\(\\kappa\\)、仲裁归因比例、强度档协议——<a href="/llm/rm-data-sources">数据单元</a>的全部口径，缺项即退回。偏置审计层：长度系数 \\(\\beta\\) 与反事实改写的 \\(\\Delta r\\) 分布（<a href="/llm/rm-length-bias">长度课</a>、<a href="/llm/rm-style-bias">风格课</a>的口径），按域报告，设上限。性能门层：分域持有准确率下限（不是全局均值），公共基准子集（<a href="/llm/rm-benchmarks">基准课</a>的漏斗顶端）。稳定性层：三个种子的重训，分数的秩相关（Spearman）下限与分数分布的 KS 检验；种子间排序不稳的 RM 说明训练本身欠收敛。端到端层：固定预算的小规模 RL 试跑，金标不掉、平均长度与格式统计不漂（<a href="/llm/rm-ensemble-fair-baseline">公平比较课</a>的协议，只有一项也要跑）。</p>',8)),(l(),t(i,null,{default:B(()=>[s(A,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20NEW%5B%22%E6%96%B0%E7%89%88%20RM%20%E8%AE%AD%E7%BB%83%E5%AE%8C%E6%88%90%22%5D%20--%3E%20CARD%7B%22%E6%95%B0%E6%8D%AE%E5%8D%A1%E9%BD%90%E5%85%A8%3F%22%7D%0A%20%20CARD%20--%3E%7C%E5%90%A6%7C%20REJ%5B%22%E9%80%80%E5%9B%9E%E8%A1%A5%E9%BD%90%22%5D%0A%20%20CARD%20--%3E%7C%E6%98%AF%7C%20BIAS%7B%22%E5%81%8F%E7%BD%AE%E5%AE%A1%E8%AE%A1%EF%BC%9A%CE%B2%20%E4%B8%8E%20%CE%94r%20%E8%BE%BE%E6%A0%87%3F%22%7D%0A%20%20BIAS%20--%3E%7C%E5%90%A6%7C%20REJ%0A%20%20BIAS%20--%3E%7C%E6%98%AF%7C%20PERF%7B%22%E5%88%86%E5%9F%9F%E5%87%86%E7%A1%AE%E7%8E%87%E8%BF%87%E4%B8%8B%E9%99%90%3F%22%7D%0A%20%20PERF%20--%3E%7C%E5%90%A6%7C%20REJ%0A%20%20PERF%20--%3E%7C%E6%98%AF%7C%20STAB%7B%22%E7%A7%8D%E5%AD%90%E7%A7%A9%E7%9B%B8%E5%85%B3%E4%B8%8E%E5%88%86%E5%B8%83%E7%A8%B3%E5%AE%9A%3F%22%7D%0A%20%20STAB%20--%3E%7C%E5%90%A6%7C%20REJ%0A%20%20STAB%20--%3E%7C%E6%98%AF%7C%20E2E%5B%22%E5%B0%8F%E8%A7%84%E6%A8%A1%20RL%20%E8%AF%95%E8%B7%91%EF%BC%9A%E9%87%91%E6%A0%87%E4%B8%8D%E9%99%8D%22%5D%0A%20%20E2E%20--%3E%7C%E8%BF%87%7C%20SHIP%5B%22%E6%B3%A8%E5%86%8C%E7%89%88%E6%9C%AC%EF%BC%8C%E6%8E%A5%E7%9B%91%E6%8E%A7%E4%B8%8A%E7%BA%BF%22%5D%0A%20%20E2E%20--%3E%7C%E4%B8%8D%E8%BF%87%7C%20REJ%0A%20%20SHIP%20--%3E%20WATCH%5B%22%E7%BA%BF%E4%B8%8A%E6%BC%82%E7%A7%BB%E4%B8%8E%E6%8A%BD%E6%A3%80%22%5D%0A"})]),fallback:B(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"方法",tabindex:"-1"},[e("方法 "),a("a",{class:"header-anchor",href:"#方法","aria-label":'Permalink to "方法"'},"​")],-1)),E[4]||(E[4]=a("p",null,[e("门要配三件套：数字、口径、豁免流程。数字门如「安全子域准确率 \\(\\ge 0.65\\)、长度系数 \\(|\\beta| \\le \\epsilon\\)」——阈值从上一版的实测分布定，不拍脑袋：取上版 P25 略宽作为新版的下限，防止门变成随机数生成器。口径门是引用前课的测量协议原文（改写器版本、持有集版本、评测提示列表），防止「同名不同测」。豁免流程承认清单会误伤：某项不过但业务必须上（如安全修复急发），豁免要记录风险、设回看日期，豁免不是绕过，是带息借款。门与监控的交接在最后：上线时把偏置审计的复测脚本接进线上定时任务（"),a("a",{href:"/llm/rm-ood-behavior"},"OOD 课"),e("的三代理），门内门外同一把尺。")],-1)),E[5]||(E[5]=a("p",null,[a("span",{class:"marginnote"},"数字实例看阈值怎么定：上一版 RM 的分域准确率实测分布里，安全域 P25 是 0.61——说明上一版有四分之一的抽样批次掉到 0.61 以下。新版门就设「安全域 \\(\\ge 0.61\\)」而非拍脑袋的 0.7：阈值从上一版的分布来，门才不会变成随机拒人的红灯。")],-1)),(l(),t(i,null,{default:B(()=>[s(A,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20G%5B%22%E4%B8%80%E9%81%93%E5%90%88%E6%A0%BC%E7%9A%84%E9%97%A8%20%3D%20%E4%B8%89%E4%BB%B6%E5%A5%97%22%5D%20--%3E%20N%5B%22%E6%95%B0%E5%AD%97%EF%BC%9A%E4%BB%8E%E4%B8%8A%E7%89%88%E5%AE%9E%E6%B5%8B%E5%88%86%E5%B8%83%E5%AE%9A%EF%BC%88%E4%B8%8A%E7%89%88%20P25%20%E7%95%A5%E5%AE%BD%EF%BC%89%22%5D%0A%20%20G%20--%3E%20K%5B%22%E5%8F%A3%E5%BE%84%EF%BC%9A%E5%BC%95%E7%94%A8%E5%89%8D%E8%AF%BE%E5%8D%8F%E8%AE%AE%E5%8E%9F%E6%96%87%EF%BC%8C%E9%98%B2%E5%90%8C%E5%90%8D%E4%B8%8D%E5%90%8C%E6%B5%8B%22%5D%0A%20%20G%20--%3E%20E%5B%22%E8%B1%81%E5%85%8D%E6%B5%81%E7%A8%8B%EF%BC%9A%E8%AE%B0%E5%BD%95%E9%A3%8E%E9%99%A9%20%2B%20%E8%AE%BE%E5%9B%9E%E7%9C%8B%E6%97%A5%E6%9C%9F%22%5D%0A%20%20E%20--%3E%20L%5B%22%E8%B1%81%E5%85%8D%E4%B8%8D%E6%98%AF%E7%BB%95%E8%BF%87%EF%BC%8C%E6%98%AF%E5%B8%A6%E6%81%AF%E5%80%9F%E6%AC%BE%EF%BC%9A%E5%88%B0%E6%9C%9F%E5%BF%85%E5%9B%9E%E7%9C%8B%22%5D%0A%20%20N%20--%3E%20V%5B%22%E9%97%A8%E4%B8%8D%E8%BF%87%E4%B8%8D%E4%B8%8A%E7%BA%BF%EF%BC%8C%E9%80%80%E5%9B%9E%E5%B9%B6%E5%BD%92%E5%9B%A0%22%5D%0A%20%20K%20--%3E%20V%0A"})]),fallback:B(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么是门而不是报告：报告是单向的，门是双向的——每次退回都制造一次「为什么不过」的归因，清单因此成为组织的学习机制：反复出现的失效模式，下一版就多一项。这与<a href="/llm/human-vs-auto-eval">人工评测 vs 自动评测</a>的分工一致：自动检查覆盖已知维度（便宜、可重复），评审会只裁决清单外的新形态。端到端门最贵，也是唯一能抓「判别好、引导坏」的，哪怕缩到单域单任务也要保留——跳过它等于只验了 RM 的静态面。</p><p><span class="marginnote">清单自身的回归：每半年把已放行版本重新过一遍现行门，统计误杀率（好 RM 被拦）与漏放率（坏 RM 上线）。两个数都高的门说明阈值或口径已过时，修订清单优先于修订模型。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>清单防的是已知失效，防不了新捷径：偏置审计的特征表是枚举的，表外维度（新的格式流行、新的谄媚句式）要靠<a href="/llm/red-team-eval">红队评测</a>与线上人评抽检补位。门还有组织成本：过严的门让版本冻结、修复挤在豁免通道里，反而降低整体质量——门密度要与迭代节奏联动，急修走窄门、大版本走全门。最后，清单是课程的汇点不是终点：它假设失效模式会被持续归类，而归类本身依赖前面每一课的测量口径还在被维护——口径失修，清单就退化成一排没有意义的红灯。</p><p><span class="marginnote">常见误区：初学者容易以为门越多越严越好——门过严，版本被冻结、紧急修复全挤进豁免通道，豁免成了常态后门就形同虚设。门的密度要和迭代节奏联动：急修走窄门、大版本走全门，把严的门留在真正值得拦的地方。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>清单五层：数据卡、偏置审计、分域性能门、稳定性重训、端到端 RL 试跑。</li><li>门配三件套：从上版分布定的数字阈值、引用原文的口径、带回看日期的豁免流程。</li><li>端到端门最贵也最不可省：只有它能抓「判别好、引导坏」。</li><li>退回归因是清单的学习机制；表外捷径靠红队与线上监控补位。</li><li>出处：据 Touvron 等 Llama 2、Ouyang 等 InstructGPT 的流程口径整理。</li></ul>',8))])}const R=n(C,[["render",d]]);export{u as __pageData,R as default};
